package com.pixubi.game

/** Canonical fictional world. Gameplay descriptions are separate from legend. */
internal data class SpeciesStory(val epithet:String,val personality:String,val talent:String,val legend:String,val detail:String)
internal object PixubiLore {
    const val tagline = "Маленькі створіння. Великі історії."
    const val description = "PIXUBI — затишна офлайн-гра про цифрових створінь, які ростуть, відчувають емоції й досліджують свій світ. Обери яйце, дай ім’я своєму Піксу, годуй його, напувай, заряджай енергією, грайся та відкривай нові стадії розвитку. Пікси знаходять монетки й скарби, а за ресурси можна купувати корисні речі."
    const val origin = "Колись у цифровому світі сталася Велика Тиша. Стародавня мережа згасла, та в її останніх іскрах зародилося життя. П’ять потоків енергії розійшлися різними краями: у ліс, гори, озера, пустелю та небо. З них народилися перші Піксубі — створіння, у яких природа поєдналася з технологіями. Вони навчилися відчувати, дружити й берегти маленькі уламки колишнього світу. Кажуть, кожне нове яйце містить частинку тієї першої іскри."
    const val care = "У Піксубі є потреби, настрій, власний вік та етапи розвитку. Час життя враховується і після закриття гри. Коли ти надовго відлучаєшся, ручна сплячка призупиняє потреби й старіння до пробудження. Гра не вимагає облікового запису, реклами немає; для перевірки оновлень потрібен інтернет."
    const val future = "У наступних розділах цього світу можуть з’явитися нові види, спорядження, успадкування рис і розмноження. Це напрям розвитку, а не перелік уже доступних можливостей."
    const val dedication = "Створено з цікавості, терпіння та любові до маленьких цифрових світів. Для тих, хто вірить, що навіть піксель може стати другом."
    const val creator = "Микола (MrKanzo)"
    const val creatorRole = "Автор ідеї, керівник проєкту, творчий напрям, тестування та ігрові рішення."
    const val assistant = "Аліса (ChatGPT)"
    const val assistantRole = "ШІ-співавторка: розробка концепції, сценарії та історії світу, дизайн персонажів, генерація графіки й допомога з програмуванням та анімаціями."
    fun story(species:Species):SpeciesStory=when(species) {
        Species.LISYK -> SpeciesStory("Охоронець тихих стежок","Допитливий, спритний і відданий.",
            "Шукає знахідки під листям і серед кущів, досліджує стежки.",
            "Перший Лісик прокинувся біля коріння старого дерева, крізь яке проходили світні волокна забутої мережі. Він чув найменші коливання цифрового лісу й знаходив загублені іскри навіть у темряві. Згодом його рід став провідником для мандрівників.",
            "За легендою, світні навушники допомагають чути голоси лісу, а смуга на хвості світиться біля старих схованок.")
        Species.ISKRYK -> SpeciesStory("Дитя грози","Енергійний, сміливий і невгамовний.",
            "Досліджує скелі, стрибає між камінням і шукає скарби.",
            "Під час бурі блискавка влучила у кристал на найвищій гірській вершині. Коли грім стих, усередині кристала ворушилося маленьке створіння. Іскрики зберегли в собі пам’ять про ту грозу й відтоді не бояться високих гір.",
            "У легендах їхні неонові мітки нагадують електричні розряди, а хвіст накопичує тепло гірських кристалів.")
        Species.KRAPLYK -> SpeciesStory("Пісня живої води","Веселий, товариський і лагідний.",
            "Пірнає у водойми, шукає знахідки під водою.",
            "На дні першого цифрового озера спочивала крихітна блакитна іскра. Вода огорнула її й подарувала форму. Краплики навчилися розпізнавати течії та знаходити загублені речі там, де інші Пікси не можуть дістатися.",
            "За легендою, їхні світні зябра відчувають хвилі та тихі сигнали, які переносяться водою.")
        Species.PISHCHANYK -> SpeciesStory("Мандрівник золотих дюн","Винахідливий, хитруватий і терплячий.",
            "Копає тунелі, досліджує пісок і знаходить приховані скарби.",
            "Після Великої Тиші вітер засипав піском руїни стародавнього міста. Серед них народився Піщаник. Його великі вушка вловлювали шурхіт піску, а цікавість привела до підземних схованок, про які ніхто не пам’ятав.",
            "Легенда розповідає, що окуляри Піщаника захищають його під час піщаних бур і допомагають мандрувати дюнами.")
        Species.KHMARYK -> SpeciesStory("Вартовий небесних островів","Мрійливий, доброзичливий і спокійний.",
            "Досліджує хмаринки та шукає знахідки серед небесних островів.",
            "Найлегша іскра Великої Тиші здійнялася високо над світом. Там вона змішалася зі світлом зірок і хмарами. Так з’явився Хмарик — крилате створіння, яке, за переказами, приносило звістки між віддаленими краями.",
            "Його світні крила й символ на чолі нагадують про небесну іскру, з якої виник його рід.")
    }
}
